def apply_nav_and_contact_page(apps, schema_editor):
    SiteNavItem = apps.get_model("website", "SiteNavItem")
    SitePage = apps.get_model("website", "SitePage")

    parent = SiteNavItem.objects.filter(parent__isnull=True, title="قوانین و پشتیبانی").order_by("id").first()
    if parent is None:
        legacy_protection = (
            SiteNavItem.objects.filter(parent__isnull=True, url="page:protection").order_by("id").first()
        )
        if legacy_protection is not None:
            legacy_protection.title = "قوانین و پشتیبانی"
            legacy_protection.url = "page:terms"
            legacy_protection.is_hidden = False
            legacy_protection.save(update_fields=["title", "url", "is_hidden"])
            parent = legacy_protection
        else:
            parent = SiteNavItem.objects.create(
                parent=None,
                title="قوانین و پشتیبانی",
                url="page:terms",
                order=5,
                is_hidden=False,
            )

    for title, url, order in LEGAL_CHILDREN:
        existing = SiteNavItem.objects.filter(parent=parent, url=url).order_by("id").first()
        if existing is not None:
            existing.title = title
            existing.order = order
            existing.is_hidden = False
            existing.save(update_fields=["title", "order", "is_hidden"])
        else:
            SiteNavItem.objects.create(
                parent=parent,
                title=title,
                url=url,
                order=order,
                is_hidden=False,
            )

    SitePage.objects.update_or_create(
        slug="contact",
        defaults={
            "title": "تماس با ما",
            "body": NEW_CONTACT_BODY,
            "order": 5,
            "show_in_footer": True,
        },
    )


def restore_nav_and_contact_page(apps, schema_editor):
    SiteNavItem = apps.get_model("website", "SiteNavItem")
    SitePage = apps.get_model("website", "SitePage")

    parent = SiteNavItem.objects.filter(parent__isnull=True, title="قوانین و پشتیبانی").order_by("id").first()
    if parent is not None:
        SiteNavItem.objects.filter(parent=parent).delete()
        parent.title = "حفاظت از محتوا"
        parent.url = "page:protection"
        parent.order = 5
        parent.save(update_fields=["title", "url", "order"])

    contact = SitePage.objects.filter(slug="contact").first()
    if contact is not None:
        contact.body = OLD_CONTACT_BODY
        contact.save(update_fields=["body"])


